action.command:
cd /workspace && cat > boot.mjs <<'EOF'
import { JSDOM } from 'jsdom';
import fs from 'fs';
const html = fs.readFileSync('/workspace/dist/basic/index.html','utf8');
const dom = new JSDOM(html, {url:'http://localhost:8099/basic/index.html', runScripts:'outside-only', pretendToBeVisual:true});
globalThis.window = dom.window; globalThis.document = dom.window.document;
globalThis.HTMLElement = dom.window.HTMLElement; globalThis.Node = dom.window.Node;
globalThis.customElements = dom.window.customElements;
globalThis.requestAnimationFrame = (cb)=>setTimeout(cb,0);
globalThis.CustomEvent = dom.window.CustomEvent;
const bundle = fs.readFileSync('/workspace/dist/mastercode/3_26_1_410dc25_git_last_commit_at_2026-09-23__10-05-39/js/masterportal.js','utf8');
try {
  await import('data:text/javascript;base64,'+Buffer.from(bundle).toString('base64'));
  console.log('MODULE_IMPORTED_OK');
} catch(e){ console.log('IMPORT_ERR:', e.constructor.name, String(e.message).slice(0,400)); }
EOF
timeout 150 node boot.mjs 2>&1 | tail -25; rm -f boot.mjs

